import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextLong();
        long[] b = new long[(int) m];
        for (int i = 0; i < b.length; i++) b[i] = sc.nextLong();

        StringBuilder sb = new StringBuilder();
        int i = 0, j = 0;
        while (i < n || j < m) {
            long x;
            if (j >= m || (i < n && a[i] <= b[j])) x = a[i++];
            else x = b[j++];
            sb.append(x).append(i < n || j < m ? " " : "\n");
        }
        System.out.print(sb);
    }
}
